    "mbcda964eb3f1": "Isomode.",
    "m7ed2ed2bde4d": "سىن ھاسىل قىلىش تەلىپى",
    "m22dc318dbe0f": "ئاۋاز كۆرۈنمە يۈزى ئاۋاز لايىھىلەش ، ئاۋاز كلونلاش ۋە TTS نۇتۇق بىرىكتۈرۈشنى بىر تۇتاش زىيارەت قىلالايدۇ. بىلەن باشلاڭ",
    "m8af2350cfd65": "of",
    "meea50f4175bf": "press",
    "m75b23637c80a": "مودېلنى تاللاڭ: ئاۋاز لايىھىلەش تەرجىمىھالى",
    "mde1d5dd076fb": "with",
    "m5aa750148a1a": "، ئاۋاز كلونلاش",
    "m1e055fccd727": "(ياكى",
    "m0cc486559160": "), TTS يوللاش",
    "m7f4ebe4ba68e": "، ئىشلەتسىڭىزمۇ بولىدۇ",
    "mcab3911dfb7f": "بىۋاسىتە بىرىكتۈرۈش. ۋەزىپە چوقۇم بىرلىككە كەلگەن ۋەزىپە كۆرۈنمە يۈزىنى راي سىناش كېرەك. ھەقىقىي ئاۋاز مۇۋەپپەقىيەتلىك چۈشۈرۈلگەن ۋە ساقلانغاندىن كېيىن ئاندىن نومۇر چىقىرىۋېتىلىدۇ. مەغلۇبىيەت ۋە 30 مىنۇتلۇق ۋاقىت نومۇرنى تۇتۇپ قالمايدۇ. Canvas ئاۋاز تۈگۈنىنى قايتا يېزىشقا توغرا كەلگەندە ، تەلەپكە قوشۇڭ",
    "m847cc897cf41": "ئاۋاز لايىھىلەش ، ئاۋاز كلونلاش ۋە TTS",
    "m5293d4ba41fa": "قۇرۇش كۆرۈنمە يۈزى ئادەتتە ۋەزىپە كىملىكىنى قايتۇرىدۇ. ۋاكالەتچى بېلەت تاشلىشى كېرەك",
    "m6fc7ea2a3912": "، دۆلەت كىرگۈچە",
    "m039fe48058cb": "ئاخىرقى ھالەتنى ساقلاڭ ، ئاندىن نەتىجە URL ياكى خاتالىق چۈشەندۈرۈشىنى ئىشلەتكۈچىگە قايتۇرۇڭ.",
    "m30acc3ecc74b": "بېلەت تاشلاش ۋەزىپىسى",
    "mf7e971a1e128": "ئىشلەتكۈچى ئېنىق ھالدا نەتىجىنى ھازىرقى كانۋا تۈگۈنىگە يېزىشنى تەلەپ قىلغاندا ، ئەۋلاد تەلىپى ئېلىپ بارالايدۇ",
    "m729d327b06c2": ". نۆۋەتتە تەۋسىيە قىلىندى",
    "mf79eade3afe4": "، ئۇ پەقەت نىشان تۈگۈنىنىڭ چىقىرىش ئورنىنى ئالىدۇ ۋە باشقا كانۋا قۇرۇلمىسىنى ئۆزگەرتمەيدۇ.",
    "m7458f19c733e": "مەۋجۇت كاناي تۈگۈنىنى قايتا يېزىڭ",
    "m455be382d5d4": "ھېسابات ۋە بوشلۇق",
    "mbd295a4038a4": "Skills API نۇقتا ، گۇرۇپپا بوشلۇقى ياكى مودېل يۈرۈشلۈك قائىدىلىرىنى ئايلىنىپ ئۆتمەيدۇ. بوشلۇق پارامېتىرلىرىنى شەخسىي بوشلۇققا قالدۇرۇشقا بولىدۇ. گۇرۇپپا بوشلۇق ۋەزىپىلىرىنى تاپشۇرۇش كېرەك",
    "mbfa48c649732": "ۋە ماس كېلىدۇ",
    "m032c41fcdb4c": ". ئەگەر كۆرۈنمە يۈزى بىر بولاق ياكى تەڭپۇڭلۇق خاتالىقىنى قايتۇرسا ، ۋاكالەتچى قايتا سىناپ بېقىشنى توختىتىشى ھەمدە سەۋەبىنى ئىشلەتكۈچىگە ئۇقتۇرۇشى كېرەك.",
    "mab8f33d375d6": "گۇرۇپپا بوشلۇق مۇھىتى",
    "md4c908b6f8a9": "خاتالىق بىر تەرەپ قىلىش",
    "m533d81ad7f55": "ۋاكالەتچى خاتالىق كودىنى ئىشلەتكۈچى قوللىنىدىغان كېيىنكى باسقۇچقا تەرجىمە قىلىشى كېرەك. دەلىللەش ، مودېل بولىقى ، نۇقتا ، ئىجازەت ۋە ۋەزىپە قاتارلىق خاتالىقلار بولسا ، قارىغۇلارچە قايتا سىناپ باقماڭ.",
    "ma38a95717057": "API ئاچقۇچى يوقاپ كەتتى ، ماسلاشمىدى ياكى ماسلاشمىدى. ئىشلەتكۈچى يېڭى كۇنۇپكىنى كۆچۈرۈش ئۈچۈن كاناي ماھارەت تاختىسىغا قايتىپ كەلسۇن.",
    "me2ef3566aa4f": "API ئاچقۇچى ئەسلىگە كەلتۈرۈلدى ياكى بىكار قىلىندى. نۆۋەتتىكى تەلەپنى توختىتىڭ ۋە ئىشلەتكۈچىدىن قايتا كۆچۈرۈشىنى تەلەپ قىلىڭ.",
    "m91d03067557f": "ھازىرقى مودېلنى ئىشلەتكىلى بولمايدۇ. مودېل تىزىملىكىنى قايتا ئوقۇڭ ، ئىشلەتكىلى بولىدىغان مودېلنى تاللاڭ ياكى ئىشلەتكۈچىنىڭ ئىجازەتنامىنى يېڭىلاش / تەقسىم قىلىشىنى تەلەپ قىلىڭ.",
    "mc20872e2bf66": "سىن قانىلى رەسىمنىڭ قايتا تەكشۈرۈلۈشىنى تەلەپ قىلدى ، ئەمما رەسىم مەغلۇپ بولدى. ئىشلەتكىلى بولىدىغان رەسىمگە ئۆزگەرتىڭ ياكى ئىشلەتكۈچىدىن ئەمەلىي تۇرمۇش ماتېرىياللىرىنىڭ ئىجازەتنامىسىنى جەزملەشتۈرۈشىنى تەلەپ قىلىڭ.",
    "mc1ee3cd181a6": "رەسىمنى تەكشۈرۈش يەنىلا بىر تەرەپ قىلىنىۋاتىدۇ. ئوخشاش تەلەپنى كېيىن قايتا سىناڭ ، ياكى تەكشۈرۈشنى تەلەپ قىلمايدىغان ماتېرىيال / مودېللارنى ئىشلىتىڭ.",
    "md12b041b6270": "يېتەرلىك نۇقتا يوق. ئەۋلادنى توختىتىدۇ ۋە ئىشلەتكۈچىنىڭ بوشلۇقنى تولۇقلاش ياكى ئالماشتۇرۇشنى تەلەپ قىلىدۇ.",
    "m9ab6da0f8c17": "مودېل ، بوشلۇق ياكى كانايغا يېزىش-يېزىش ئىجازىتى يېتەرلىك ئەمەس. باشقا دەلىللەش ئۇسۇلىنى قوللانماڭ.",
    "m5b60956c042d": "ۋەزىپە ، خىزمەت ئېقىمى ياكى تۈگۈن مەۋجۇت ئەمەس. ۋەزىپە_ id ، خىزمەت ئېقىمى ، node_id نى جەزملەشتۈرۈپ قايتا سىناڭ.",
    "m1d99a2b0582b": "خاتالىق بىر تەرەپ قىلىش ئىستراتېگىيىسى",
    "mda8c682d4a2a": "تولۇق ۋاكالەتچى مىسالى",
    "m901a2e96380f": "تۆۋەندىكى مىسالدا ۋاكالەتچىنىڭ مودېلنى قانداق ئوقۇغانلىقى ، يەرلىك ھۆججەتنى يۈكلەيدىغانلىقى ، رەسىم سىزىش ۋەزىپىسىنى تاپشۇرغانلىقى ۋە راي سىناشنىڭ تاماملانغانلىقى كۆرسىتىلدى. ئەمەلىيەتتە ئىجرا بولغاندا API ئاچقۇچىنى مۇھىت ئۆزگەرگۈچى مىقدارغا ياكى ۋاكالەتچىنىڭ بىخەتەرلىك ئاچقۇچ سەپلىمىسىگە قويۇڭ.",
